(4490604, 646447, 76335, '<td valign="top">Is this natural light? Very nice. A seven for you.</td>', 'Is this natural light? Very nice. A seven for you.', '2008-02-16 12:33:28.000000', NULL, 1),
(4490611, 645693, 76335, '<td valign="top">A slice of sacrilege, I see. Well done, anyway. A seven for you.</td>', 'A slice of sacrilege, I see. Well done, anyway. A seven for you.', '2008-02-16 12:35:29.000000', NULL, 1),
(4490612, 644214, 76335, '<td valign="top">Points for originality. A seven for you.</td>', 'Points for originality. A seven for you.', '2008-02-16 12:35:41.000000', NULL, 1),
(4490613, 644654, 76335, '<td valign="top">Going gluten free? Nicely done. A seven for you.</td>', 'Going gluten free? Nicely done. A seven for you.', '2008-02-16 12:36:17.000000', NULL, 1),
(4490614, 646198, 76335, '<td valign="top">Excellent focus on this one. Great textures.</td>', 'Excellent focus on this one. Great textures.', '2008-02-16 12:36:20.000000', NULL, 1),
(4490615, 644011, 76335, '<td valign="top">Blurry. Noisy. Bread?</td>', 'Blurry. Noisy. Bread?', '2008-02-16 12:37:39.000000', NULL, 1),
(4490616, 646143, 76335, '<td valign="top">Too small.</td>', 'Too small.', '2008-02-16 12:37:56.000000', NULL, 1),
(4490617, 645783, 76335, '<td valign="top">Too little DOF.</td>', 'Too little DOF.', '2008-02-16 12:38:02.000000', NULL, 1),
(4490619, 646013, 76335, '<td valign="top">Nice try but considerably more DOF is needed.</td>', 'Nice try but considerably more DOF is needed.', '2008-02-16 12:38:49.000000', NULL, 1),
(4490656, 645932, 80859, '<td valign="top">it''s not a badly taken photo and it''s obvious you put some thought into the composition... i just don''t understand, but i give it a 5.</td>', 'it''s not a badly taken photo and it''s obvious you put some thought into the composition... i just don''t understand, but i give it a 5.', '2008-02-16 13:27:08.000000', NULL, 1),
(4490658, 646469, 80859, '<td valign="top">the lighting is a bit harsh and blew out some parts and i''m not sure what mom is doing to your sandwiches, but it looks kind of cool, so i give it a 5</td>', 'the lighting is a bit harsh and blew out some parts and i''m not sure what mom is doing to your sandwiches, but it looks kind of cool, so i give it a 5', '2008-02-16 13:31:03.000000', NULL, 1),
(4490673, 645362, 55838, '<td valign="top">Very nice colors and a fun idea.  One of the best in this challenge.  Back to bump you up to 8.</td>', 'Very nice colors and a fun idea.  One of the best in this challenge.  Back to bump you up to 8.', '2008-02-16 13:45:00.000000', NULL, 1),
(4490675, 643437, 55838, '<td valign="top">Very nice lighting and color tones.  Back to bump you up to 8.</td>', 'Very nice lighting and color tones.  Back to bump you up to 8.', '2008-02-16 13:45:37.000000', NULL, 1),
(4490679, 643783, 86799, '<td valign="top">Looks pretty good!</td>', 'Looks pretty good!', '2008-02-16 13:48:16.000000', NULL, 1),
(4490682, 643273, 86799, '<td valign="top">A picture of somebody else''s creativity?  We want to see some of YOURS!</td>', 'A picture of somebody else''s creativity?  We want to see some of YOURS!', '2008-02-16 13:50:39.000000', NULL, 1),
(4490683, 645917, 86799, '<td valign="top">Cool.  Nice approach.</td>', 'Cool.  Nice approach.', '2008-02-16 13:51:01.000000', NULL, 1),
(4490693, 645469, 55892, '<td valign="top">Bizarre!</td>', 'Bizarre!', '2008-02-16 13:58:14.000000', NULL, 1),
(4490694, 646417, 55892, '<td valign="top">unique</td>', 'unique', '2008-02-16 13:58:26.000000', NULL, 1),
(4490695, 646426, 55892, '<td valign="top">I''m pondering on this one.  It''s a creative take on the topic.  The b&amp;w gives it the older concept.  I''m inclined to think it would be more effective if the elect. cord wasn''t in the picture.</td>', 'I''m pondering on this one.  It''s a creative take on the topic.  The b&w gives it the older concept.  I''m inclined to think it would be more effective if the elect. cord wasn''t in the picture.', '2008-02-16 13:58:36.000000', NULL, 1),
(4490696, 646197, 55892, '<td valign="top">good idea, but poor focus, unrealistic composition.  Who eats tomatoes &amp; cucumbers for breakfast?</td>', 'good idea, but poor focus, unrealistic composition.  Who eats tomatoes & cucumbers for breakfast?', '2008-02-16 13:58:47.000000', NULL, 1),
(4490697, 645944, 55892, '<td valign="top">I like the blue colors.  There''s a lot of distracting reflections throughot the shot.  I just don''t get the Brainwashing part.</td>', 'I like the blue colors.  There''s a lot of distracting reflections throughot the shot.  I just don''t get the Brainwashing part.', '2008-02-16 13:58:58.000000', NULL, 1),
(4490698, 646371, 55892, '<td valign="top">Love the expression, sheer anguish.   I think the angle of the shot should show what the man is seeing;  this way it shows what you would see from the floor;  it doesn''t fit.</td>', 'Love the expression, sheer anguish.   I think the angle of the shot should show what the man is seeing;  this way it shows what you would see from the floor;  it doesn''t fit.', '2008-02-16 13:59:15.000000', NULL, 1),
(4490745, 645699, 57775, '<td valign="top">LOL - love this!  Very cute.</td>', 'LOL - love this!  Very cute.', '2008-02-16 14:36:09.000000', NULL, 1),
(4490893, 643755, 86799, '<td valign="top">Needs more focus, and some "interest.</td>', 'Needs more focus, and some "interest.', '2008-02-16 16:22:14.000000', NULL, 1),
(4490897, 644138, 86799, '<td valign="top">Cool.  Good placement of the reflection.</td>', 'Cool.  Good placement of the reflection.', '2008-02-16 16:23:00.000000', NULL, 1),
(4490900, 644775, 86799, '<td valign="top">With a little more DOF this would be really nice.  Very good idea, just needs some POP.</td>', 'With a little more DOF this would be really nice.  Very good idea, just needs some POP.', '2008-02-16 16:24:23.000000', NULL, 1),
(4490901, 644330, 86799, '<td valign="top">Very nice.</td>', 'Very nice.', '2008-02-16 16:25:15.000000', NULL, 1),
(4490905, 644076, 86799, '<td valign="top">Unique approach.  Well done.</td>', 'Unique approach.  Well done.', '2008-02-16 16:26:13.000000', NULL, 1),
(4490910, 644329, 86799, '<td valign="top">Outstanding.  Should go very high, IMO.</td>', 'Outstanding.  Should go very high, IMO.', '2008-02-16 16:27:16.000000', NULL, 1),
(4491153, 643755, 62249, '<td valign="top">Work on composition, lighting, and tonal range.</td>', 'Work on composition, lighting, and tonal range.', '2008-02-16 18:26:08.000000', NULL, 1),
(4491172, 646308, 62249, '<td valign="top">Lovely! Very well composed, and lighting and color are just right.</td>', 'Lovely! Very well composed, and lighting and color are just right.', '2008-02-16 18:40:38.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4491173, 643437, 62249, '<td valign="top">Nicely composed and very well lit.</td>', 'Nicely composed and very well lit.', '2008-02-16 18:40:43.000000', NULL, 1),
(4491175, 646430, 62249, '<td valign="top">Cool! What did you use to light the bottom of the toaster slots?</td>', 'Cool! What did you use to light the bottom of the toaster slots?', '2008-02-16 18:40:53.000000', NULL, 1),
(4491176, 645699, 62249, '<td valign="top">VERY cute!</td>', 'VERY cute!', '2008-02-16 18:41:03.000000', NULL, 1),
(4491177, 645362, 62249, '<td valign="top">Clever!</td>', 'Clever!', '2008-02-16 18:41:21.000000', NULL, 1),
(4491178, 645800, 62249, '<td valign="top">Nicely lit. Golden color is appealing.</td>', 'Nicely lit. Golden color is appealing.', '2008-02-16 18:41:47.000000', NULL, 1),
(4491179, 643860, 62249, '<td valign="top">Very nice. I like the backlighting and the graphic quality of the plate. Would have been nice to have  adjusted the backlighting a little bit to have the upper edge of the bread separated from the background.</td>', 'Very nice. I like the backlighting and the graphic quality of the plate. Would have been nice to have  adjusted the backlighting a little bit to have the upper edge of the bread separated from the background.', '2008-02-16 18:41:50.000000', NULL, 1),
(4491180, 646421, 62249, '<td valign="top">Excellent perspective! I like the creativity of this one.</td>', 'Excellent perspective! I like the creativity of this one.', '2008-02-16 18:42:11.000000', NULL, 1),
(4491181, 646138, 62249, '<td valign="top">Good use of B/W. I like the way this one tells a story.</td>', 'Good use of B/W. I like the way this one tells a story.', '2008-02-16 18:42:17.000000', NULL, 1),
(4491182, 644329, 62249, '<td valign="top">Cute! And good detail on bread.</td>', 'Cute! And good detail on bread.', '2008-02-16 18:42:29.000000', NULL, 1),
(4491183, 646042, 62249, '<td valign="top">Nicely composed and lit. Just right DOF. 7</td>', 'Nicely composed and lit. Just right DOF. 7', '2008-02-16 18:43:18.000000', NULL, 1),
(4491184, 646447, 62249, '<td valign="top">Very nice. Tells a good story. B/W was a good choice for this shot.</td>', 'Very nice. Tells a good story. B/W was a good choice for this shot.', '2008-02-16 18:43:20.000000', NULL, 1),
(4491185, 646289, 62249, '<td valign="top">B/W was a good choice for this one.</td>', 'B/W was a good choice for this one.', '2008-02-16 18:43:30.000000', NULL, 1),
(4491187, 646469, 62249, '<td valign="top">Weird but interesting. Cropped just a hair too tight. Would like a bit more "breathing room" around edges of bread.</td>', 'Weird but interesting. Cropped just a hair too tight. Would like a bit more "breathing room" around edges of bread.', '2008-02-16 18:43:44.000000', NULL, 1),
(4491188, 643547, 62249, '<td valign="top">It''s a little disturbing to note that the pink of his hands closely matches that of the corned beef... (eeww!) But--I like the shot. Tells a good story.</td>', 'It''s a little disturbing to note that the pink of his hands closely matches that of the corned beef... (eeww!) But--I like the shot. Tells a good story.', '2008-02-16 18:44:04.000000', NULL, 1),
(4491189, 646197, 62249, '<td valign="top">Interesting setup. Personally, I''d like it even better with greater DOF.</td>', 'Interesting setup. Personally, I''d like it even better with greater DOF.', '2008-02-16 18:45:04.000000', NULL, 1),
(4491192, 645698, 62249, '<td valign="top">Nicely composed. Knife looks oversharpened, though (no pun intended).</td>', 'Nicely composed. Knife looks oversharpened, though (no pun intended).', '2008-02-16 18:47:15.000000', NULL, 1),
(4491193, 646426, 62249, '<td valign="top">Clever idea. Tops of toast slices aren''t distinct enough from the dark band in the tile background, and bottom of coffee cup is oddly cut off. Good choice to use B/W for this.</td>', 'Clever idea. Tops of toast slices aren''t distinct enough from the dark band in the tile background, and bottom of coffee cup is oddly cut off. Good choice to use B/W for this.', '2008-02-16 18:47:36.000000', NULL, 1),
(4491194, 646245, 62249, '<td valign="top">Funny. Watch out for crumbs on dark surfaces in Basic editing. Ya can''t clone ''em out.</td>', 'Funny. Watch out for crumbs on dark surfaces in Basic editing. Ya can''t clone ''em out.', '2008-02-16 18:47:58.000000', NULL, 1),
(4491198, 645485, 62249, '<td valign="top">Decent tonal range that shows off the flakiness of the croissant.</td>', 'Decent tonal range that shows off the flakiness of the croissant.', '2008-02-16 18:48:46.000000', NULL, 1),
(4491199, 646044, 62249, '<td valign="top">Amusing. This is what happens when your woody gets you into trouble ;-).</td>', 'Amusing. This is what happens when your woody gets you into trouble ;-).', '2008-02-16 18:48:49.000000', NULL, 1),
(4491200, 646265, 62249, '<td valign="top">Kinda yellow, but I like the composition and close crop.</td>', 'Kinda yellow, but I like the composition and close crop.', '2008-02-16 18:49:14.000000', NULL, 1),
(4491201, 646417, 45475, '<td valign="top">Nice balance you have there ;) Cool shot. Love the colour.</td>', 'Nice balance you have there ;) Cool shot. Love the colour.', '2008-02-16 18:49:27.000000', NULL, 1),
(4491202, 645328, 62249, '<td valign="top">Like the composition. Would be nice if there was a bit more detail in the midrange (in the folds of his jacket, for example).</td>', 'Like the composition. Would be nice if there was a bit more detail in the midrange (in the folds of his jacket, for example).', '2008-02-16 18:49:49.000000', NULL, 1),
(4491203, 646353, 62249, '<td valign="top">Looks tasty. Nice tonal range.</td>', 'Looks tasty. Nice tonal range.', '2008-02-16 18:49:58.000000', NULL, 1),
(4491204, 644701, 62249, '<td valign="top">A pleasing shot that makes the bread look appealing. Would like to see a bit more of the basket in the foreground in the lower right corner and a tad more DOF so that the second roll was a little sharper.</td>', 'A pleasing shot that makes the bread look appealing. Would like to see a bit more of the basket in the foreground in the lower right corner and a tad more DOF so that the second roll was a little sharper.', '2008-02-16 18:50:05.000000', NULL, 1),
(4491205, 645896, 62249, '<td valign="top">This shot has potential, but the composition isn''t quite compelling enough, especially for a Bread challenge. The book and the chair are far more noticeable than the bread, which almost disappears on the plate.</td>', 'This shot has potential, but the composition isn''t quite compelling enough, especially for a Bread challenge. The book and the chair are far more noticeable than the bread, which almost disappears on the plate.', '2008-02-16 18:50:10.000000', NULL, 1),
(4491206, 646428, 62249, '<td valign="top">Pretty funny. Have you tried selling this on eBay? And I think this looks like a portrait of  Judi.</td>', 'Pretty funny. Have you tried selling this on eBay? And I think this looks like a portrait of  Judi.', '2008-02-16 18:50:33.000000', NULL, 1),
(4491207, 646488, 62249, '<td valign="top">A nice, homey-looking scene.</td>', 'A nice, homey-looking scene.', '2008-02-16 18:50:39.000000', NULL, 1),
(4491208, 646474, 62249, '<td valign="top">I like this composition a lot, especially w/ DOF blurring the background. Wish bread itself was sharper.</td>', 'I like this composition a lot, especially w/ DOF blurring the background. Wish bread itself was sharper.', '2008-02-16 18:50:45.000000', NULL, 1),
(4491209, 646454, 62249, '<td valign="top">Flame is nicely captured. Shot needs greater DOF.</td>', 'Flame is nicely captured. Shot needs greater DOF.', '2008-02-16 18:51:07.000000', NULL, 1),
(4491210, 644138, 62249, '<td valign="top">Creative concept, and I''m sure this setup was tricky to shoot in a way that obscured the camera. The shot doesn''t have that "pop" to make it a super high scorer, though. It''s nice, but not "Wow!"</td>', 'Creative concept, and I''m sure this setup was tricky to shoot in a way that obscured the camera. The shot doesn''t have that "pop" to make it a super high scorer, though. It''s nice, but not "Wow!"', '2008-02-16 18:51:12.000000', NULL, 1),
(4491211, 645410, 62249, '<td valign="top">Too yellow, and no sign of ham. But nice detail on upper edge of foreground roll.</td>', 'Too yellow, and no sign of ham. But nice detail on upper edge of foreground roll.', '2008-02-16 18:51:21.000000', NULL, 1),
(4491212, 645542, 62249, '<td valign="top">Distracting crumbs in foreground, and lighting from left is a little too hot.</td>', 'Distracting crumbs in foreground, and lighting from left is a little too hot.', '2008-02-16 18:51:51.000000', NULL, 1),
(4491213, 644330, 45475, '<td valign="top">Very nice work. Great tones.</td>', 'Very nice work. Great tones.', '2008-02-16 18:51:55.000000', NULL, 1),
(4491214, 646006, 62249, '<td valign="top">Crumbs detract from overall photo.</td>', 'Crumbs detract from overall photo.', '2008-02-16 18:52:10.000000', NULL, 1),
(4491215, 645809, 62249, '<td valign="top">Foreground pink bottlecap is distracting, but otherwise it''s a cute shot.</td>', 'Foreground pink bottlecap is distracting, but otherwise it''s a cute shot.', '2008-02-16 18:52:13.000000', NULL, 1),
(4491216, 645376, 62249, '<td valign="top">Funny.</td>', 'Funny.', '2008-02-16 18:52:18.000000', NULL, 1),
(4491217, 646428, 45475, '<td valign="top">Oh this can''t have been easy... clever work!</td>', 'Oh this can''t have been easy... clever work!', '2008-02-16 18:52:29.000000', NULL, 1),
(4491219, 646313, 62249, '<td valign="top">I like the lighting on the breadsticks, and I appreciate the experimental cropping, but... might been better cropped as a vertical. You still could''ve left lots of black on the left, just not as much as in this horizontal arrangement.</td>', 'I like the lighting on the breadsticks, and I appreciate the experimental cropping, but... might been better cropped as a vertical. You still could''ve left lots of black on the left, just not as much as in this horizontal arrangement.', '2008-02-16 18:53:46.000000', NULL, 1),
(4491220, 644214, 62249, '<td valign="top">Amusing. Blue background''s got some distracting texture and/or noise in it.</td>', 'Amusing. Blue background''s got some distracting texture and/or noise in it.', '2008-02-16 18:54:06.000000', NULL, 1),
(4491221, 644610, 62249, '<td valign="top">Lighting on this is a bit harsh, and the flower seems an odd addition in terms of shape, color, and fit with the challenge. Still, you get points for that wild-looking loaf. It''s surely one of a kind.</td>', 'Lighting on this is a bit harsh, and the flower seems an odd addition in terms of shape, color, and fit with the challenge. Still, you get points for that wild-looking loaf. It''s surely one of a kind.', '2008-02-16 18:54:11.000000', NULL, 1),
(4491222, 645991, 62249, '<td valign="top">Interesting idea and good title. I thought of trying something similar but found it too hard to light. This would be even cooler if the slices were uniformly sharp in focus.</td>', 'Interesting idea and good title. I thought of trying something similar but found it too hard to light. This would be even cooler if the slices were uniformly sharp in focus.', '2008-02-16 18:54:16.000000', NULL, 1),
(4491223, 646476, 62249, '<td valign="top">Fun idea.</td>', 'Fun idea.', '2008-02-16 18:54:33.000000', NULL, 1),
(4491224, 646410, 62249, '<td valign="top">Looks like a tasty breakfast. I like the addition of the orange.</td>', 'Looks like a tasty breakfast. I like the addition of the orange.', '2008-02-16 18:54:37.000000', NULL, 1),
(4491225, 645917, 62249, '<td valign="top">Lighting is a bit harsh, but it''s a cool looking loaf.</td>', 'Lighting is a bit harsh, but it''s a cool looking loaf.', '2008-02-16 18:54:41.000000', NULL, 1),
(4491229, 645783, 62249, '<td valign="top">Not much tonal range.</td>', 'Not much tonal range.', '2008-02-16 18:55:54.000000', NULL, 1),
(4491230, 644593, 62249, '<td valign="top">Needs better lighting. Reflection of overhead lights in upper right section of bread maker is distracting, as are the dark specks above the control panel.</td>', 'Needs better lighting. Reflection of overhead lights in upper right section of bread maker is distracting, as are the dark specks above the control panel.', '2008-02-16 18:55:59.000000', NULL, 1),
(4491231, 646176, 62249, '<td valign="top">Work on the lighting. Although reasonably well composed, the scene is very flat looking.</td>', 'Work on the lighting. Although reasonably well composed, the scene is very flat looking.', '2008-02-16 18:56:18.000000', NULL, 1),
(4491232, 646443, 62249, '<td valign="top">Work on your lighting to try to bring out edge details without harsh shadows.</td>', 'Work on your lighting to try to bring out edge details without harsh shadows.', '2008-02-16 18:56:26.000000', NULL, 1),
(4491234, 646208, 62249, '<td valign="top">Too grainy, and work on color cast.</td>', 'Too grainy, and work on color cast.', '2008-02-16 18:57:03.000000', NULL, 1),
(4491235, 643426, 62249, '<td valign="top">Good DOF, but composition is kinda dull.</td>', 'Good DOF, but composition is kinda dull.', '2008-02-16 18:57:35.000000', NULL, 1),
(4491236, 645409, 62249, '<td valign="top">Work on color cast.</td>', 'Work on color cast.', '2008-02-16 18:57:44.000000', NULL, 1),
(4491237, 645269, 62249, '<td valign="top">Funny. Lighting is a bit harsh.</td>', 'Funny. Lighting is a bit harsh.', '2008-02-16 18:57:56.000000', NULL, 1),
(4491238, 645468, 62249, '<td valign="top">Composition is decent. Work on tonal range and sharper focus.</td>', 'Composition is decent. Work on tonal range and sharper focus.', '2008-02-16 18:58:03.000000', NULL, 1),
(4491239, 646416, 62249, '<td valign="top">Composition needs work. EIther pick the subject on the left (which is the more interesting of the two), or the one on the right, but not both.</td>', 'Composition needs work. EIther pick the subject on the left (which is the more interesting of the two), or the one on the right, but not both.', '2008-02-16 18:58:07.000000', NULL, 1),
(4491240, 645840, 62249, '<td valign="top">Weird color cast.</td>', 'Weird color cast.', '2008-02-16 18:58:25.000000', NULL, 1),
(4491241, 645890, 62249, '<td valign="top">This shot has potential but lighting needs work. Try this in B/W and fiddle with tonal range.</td>', 'This shot has potential but lighting needs work. Try this in B/W and fiddle with tonal range.', '2008-02-16 18:59:58.000000', NULL, 1),
(4491242, 643987, 62249, '<td valign="top">Needs greater depth of field to bring more of the top slice into focus.</td>', 'Needs greater depth of field to bring more of the top slice into focus.', '2008-02-16 19:00:11.000000', NULL, 1),
(4491247, 646301, 62249, '<td valign="top">Interesting bread shapes, but the arrangement is too chaotic. Arrange the bread deliberately to help guide the viewer''s eye through the shot. Color is a bit too yellow overall, and the red/green bits in the upper left corner are distracting.</td>', 'Interesting bread shapes, but the arrangement is too chaotic. Arrange the bread deliberately to help guide the viewer''s eye through the shot. Color is a bit too yellow overall, and the red/green bits in the upper left corner are distracting.', '2008-02-16 19:00:51.000000', NULL, 1),
(4491249, 645689, 62249, '<td valign="top">What a pretty plate and tasty-looking loaf. However, the lighting needs work.</td>', 'What a pretty plate and tasty-looking loaf. However, the lighting needs work.', '2008-02-16 19:01:27.000000', NULL, 1),
(4491251, 646338, 62249, '<td valign="top">Nice idea, but the lighting and composition aren''t particularly interesting, nor is the angle of the shot.</td>', 'Nice idea, but the lighting and composition aren''t particularly interesting, nor is the angle of the shot.', '2008-02-16 19:02:13.000000', NULL, 1),
(4491252, 645973, 62249, '<td valign="top">Work on the color cast. This is WAY too yellow. It also has a distracting background and harsh shadows.</td>', 'Work on the color cast. This is WAY too yellow. It also has a distracting background and harsh shadows.', '2008-02-16 19:02:39.000000', NULL, 1),
(4491253, 644011, 62249, '<td valign="top">The bread might be whole grain, but the photo shouldn''t be :-). Use better lighting and lower ISO.</td>', 'The bread might be whole grain, but the photo shouldn''t be :-). Use better lighting and lower ISO.', '2008-02-16 19:02:51.000000', NULL, 1),
(4491255, 646415, 62249, '<td valign="top">It''s a decent idea, but the composition is lacking. Crumbs are distracting.</td>', 'It''s a decent idea, but the composition is lacking. Crumbs are distracting.', '2008-02-16 19:03:08.000000', NULL, 1),
(4491256, 646209, 62249, '<td valign="top">Poorly lit and very unappealing composition. It''s not that you can''t do in-your-face, unattractive photos (although they don''t often fare well with voters here), but you need to do them with more technical skill (better lighting, better contrast, sharper focus, etc.)</td>', 'Poorly lit and very unappealing composition. It''s not that you can''t do in-your-face, unattractive photos (although they don''t often fare well with voters here), but you need to do them with more technical skill (better lighting, better contrast, sharper focus, etc.)', '2008-02-16 19:03:32.000000', NULL, 1),
(4491257, 646143, 62249, '<td valign="top">Too small to really give us a good look at the interesting surface texture. You''ve got 640 pixels to play with--use ''em.</td>', 'Too small to really give us a good look at the interesting surface texture. You''ve got 640 pixels to play with--use ''em.', '2008-02-16 19:03:39.000000', NULL, 1),
