(4496161, 645767, 59415, '<td valign="top">Great portrait that incorperates the theme of the challenge.  Good job.</td>', 'Great portrait that incorperates the theme of the challenge.  Good job.', '2008-02-18 22:12:14.000000', NULL, 1),
