(4499346, 646478, 83313, '<td valign="top">Looks a little well done. Nice lighting and tone on this.</td>', 'Looks a little well done. Nice lighting and tone on this.', '2008-02-19 23:53:07.000000', NULL, 1),
(4499347, 646054, 83313, '<td valign="top">Just cute! gotta love it.</td>', 'Just cute! gotta love it.', '2008-02-19 23:53:22.000000', NULL, 1),
