(4499352, 646243, 83313, '<td valign="top">Really great details and lighting on this.</td>', 'Really great details and lighting on this.', '2008-02-19 23:54:59.000000', NULL, 1),
(4499356, 646245, 31535, '<td valign="top">Very funny. Too bad its basic or you could have cloned out all the white specks.</td>', 'Very funny. Too bad its basic or you could have cloned out all the white specks.', '2008-02-19 23:56:15.000000', NULL, 1),
