(4499360, 643437, 83313, '<td valign="top">Nice contrast and colors. Cropped in a little more would show off more detail, but that''s a nitpick.</td>', 'Nice contrast and colors. Cropped in a little more would show off more detail, but that''s a nitpick.', '2008-02-19 23:57:15.000000', NULL, 1),
(4499361, 644701, 31535, '<td valign="top">Simple and clean. Focus is spot on as well.</td>', 'Simple and clean. Focus is spot on as well.', '2008-02-19 23:57:41.000000', NULL, 1),
(4499363, 644440, 83313, '<td valign="top">Nice street view of this, though it looks like a fairly "white bread" sort of shot.</td>', 'Nice street view of this, though it looks like a fairly "white bread" sort of shot.', '2008-02-19 23:58:20.000000', NULL, 1),
